    }
    public JsonObject Decide(JsonObject input)
    {
        var why=new JsonArray();double points=0,fine=0;bool strong=false,canReturn=false;var deeds=A(input["deeds"]);var record=input["record"];
        foreach(var deed in deeds){var t=Data["things"]?[S(deed,"thing")]??throw new NativeServiceException("unknown deed");double p=N(t,"severity")+(B(deed,"owner_saw")?1:0),f=N(t,"fine_c");if(!B(deed,"seen")){p=Math.Max(1,Math.Floor(p/2));f=Math.Floor(f/2+.5);}if(B(deed,"returned")){p=Math.Floor(p/2);f=Math.Floor(f/2+.5);}else canReturn=true;if(B(deed,"owner_saw")||N(deed,"witnesses")>=2)strong=true;points+=p;fine+=f;why.Add($"{S(deed,"thing")}{(B(deed,"owner_saw")?", the owner saw":B(deed,"seen")?", seen":", talk only")}{(B(deed,"returned")?", given back":"")}: {p}");}
        double r=N(record,"warnings")+N(record,"fines")*2+N(record,"arrests")*3+N(record,"fled")+Math.Min(2,N(record,"lies"));if(r>0)why.Add($"record: {r}");points+=r;double fled=N(input,"fledNow");if(fled>0){points+=3*fled;why.Add($"ran from the agent: {3*fled}");}bool food=deeds.Count>0&&deeds.All(d=>S(d,"thing")=="food");string stance=S(input,"stance");int st=stance=="confess"?-1:stance=="return"&&canReturn?-1:stance=="excuse"&&food?-1:stance=="deny"&&strong?1:0;if(st!=0)why.Add($"{stance}: {st}");double story=N(input["story"],"points");if(story!=0)why.Add($"his story: {story}");double raw=points+st+story;points=Math.Max(0,raw);bool trueStory=B(input["story"],"trueStory");string reason=S(input,"reason"),verdict=reason=="deed"?"fine":"warning";double before=N(record,"fines")+N(record,"arrests");if(points>=8||fled>0&&points>=5||before>=2)verdict="arrest";else if(points>=3||N(record,"warnings")>=1&&!trueStory||N(record,"fines")>=1)verdict="fine";if(stance=="refuse"&&verdict!="arrest"){verdict="arrest";why.Add("he will not pay");}if(reason=="talk"&&verdict=="arrest"&&fled==0&&before<2&&stance!="refuse")verdict="fine";
        if((verdict=="warning"||verdict=="fine"&&points<3)&&trueStory&&raw<=0&&N(record,"fines")==0&&N(record,"arrests")==0&&N(record,"fled")==0&&fled==0){verdict="let_off";why.Add("a true story, believed: let off");}fine+=10*N(record,"fines");if(stance=="confess")fine*=.8;int fineIf=Math.Clamp((int)Math.Floor(fine/5+.5)*5,10,150),fineC=verdict is "warning"or"let_off"?0:fineIf;if(verdict=="fine"&&N(input,"money_c")<fineC){verdict="arrest";why.Add($"cannot pay {fineC} c");}return new(){["verdict"]=verdict,["fine_c"]=fineC,["fine_if_c"]=fineIf,["points"]=points,["why"]=why};
    }
    public void Schedule(int player,int deed,int delay=20,string? agent=null)
    {
        var state=PoliceState(player);var visit=state["visit"]as JsonObject;if(visit==null){visit=new JsonObject{["id"]=N(state,"nextId",1),["reason"]="deed",["deeds"]=new JsonArray(deed),["due"]=Minute+delay,["state"]="due",["agent"]=null,["fled"]=0,["offered"]=new JsonObject(),["calls"]=0};state["nextId"]=N(state,"nextId",1)+1;state["visit"]=visit;}else{if(!A(visit["deeds"]).Any(d=>V(d)==deed))visit["deeds"]!.AsArray().Add(deed);visit["reason"]="deed";if(S(visit,"state")=="due")visit["due"]=Math.Min(N(visit,"due"),Minute+delay);}
        if(agent!=null&&S(visit,"state")=="due"&&!BusyAgents(player).Contains(agent)){visit["state"]="coming";visit["agent"]=agent;visit["due"]=Minute;C.Log(player,"police_sent",agent,$"{Name(agent)} of the police saw a theft and came for Jef.");}SavePolice(player,state);C.Log(player,"police_called",deed.ToString(),"Someone went for the police about a theft.");
    }
    private HashSet<string> BusyAgents(int except){var result=new HashSet<string>();foreach(var p in C.Rows("SELECT id FROM player")){int pid=(int)N(p,"id");var visit=PoliceState(pid)["visit"];if(pid!=except&&visit!=null&&S(visit,"state")!="due"&&S(visit,"agent")!="")result.Add(S(visit,"agent"));}return result;}
    private JsonObject[] Duty()=>C.Rows("SELECT data_json FROM resident WHERE trade='police'").Select(row=>JsonNode.Parse(S(row,"data_json"))!.AsObject()).Where(r=>NativeShops.Activity(r,Day,Hour).act=="work").ToArray();
    private void PoliceTick(int player)
    {
        var state=PoliceState(player);var visit=state["visit"]as JsonObject;var open=C.Rows("SELECT * FROM deed WHERE status='open' AND player_id=$p0",player);if(visit==null&&open.Any(d=>(N(d,"day")-1)*1440+N(d,"hour")*60+N(d,"minute")>N(state,"settledAt",-1))&&N(state,"talkDay")!=Day&&TalkCount(player)>=10){state["visit"]=new JsonObject{["id"]=N(state,"nextId",1),["reason"]="talk",["deeds"]=new JsonArray(open.Select(d=>(JsonNode)JsonValue.Create((int)N(d,"id"))!).ToArray()),["due"]=Minute+30,["state"]="due",["agent"]=null,["fled"]=0,["offered"]=new JsonObject()};state["nextId"]=N(state,"nextId",1)+1;state["talkDay"]=Day;visit=state["visit"]!.AsObject();}
        if(visit!=null&&S(visit,"state")!="talking"){var duty=Duty();if(S(visit,"state")=="coming"&&!duty.Any(r=>S(r,"id")==S(visit,"agent"))){visit["state"]="due";visit["agent"]=null;}if(S(visit,"state")=="due"&&Minute>=N(visit,"due")){var deed=Row((int)V(A(visit["deeds"]).LastOrDefault()));var busy=BusyAgents(player);var agent=duty.Where(r=>!busy.Contains(S(r,"id"))).OrderBy(r=>A(r["work"]?["route"]).Select(p=>NativeGoods.Distance(V(A(p).ElementAtOrDefault(0)),V(A(p).ElementAtOrDefault(1)),N(deed,"x"),N(deed,"z"))).DefaultIfEmpty(double.PositiveInfinity).Min()).FirstOrDefault();if(agent==null)visit["due"]=Minute+30;else{visit["state"]="coming";visit["agent"]=S(agent,"id");C.Log(player,"police_sent",S(agent,"id"),$"{Name(S(agent,"id"))} of the police set out to find Jef.");}}}SavePolice(player,state);
    }
    private void Settled(int player,int deed,string thing){var state=PoliceState(player);var visit=state["visit"]as JsonObject;if(visit==null||S(visit,"state")=="talking")return;if(N(Data["things"]?[thing],"severity")<=2)visit["deeds"]=new JsonArray(A(visit["deeds"]).Where(d=>V(d)!=deed).Select(d=>d!.DeepClone()).ToArray());if(A(visit["deeds"]).Count==0&&N(visit,"fled")==0)state["visit"]=null;SavePolice(player,state);}
    private JsonObject[] VisitDeeds(int player,JsonObject visit)=>A(visit["deeds"]).Select(d=>Row((int)V(d))).Where(d=>d!=null&&N(d,"player_id",1)==player&&S(d,"status")is "open"or"returned").Cast<JsonObject>().ToArray();
    public JsonObject? Talk(NativeServiceRequest r)
    {
        string id=r.Param("id");var state=PoliceState(r.PlayerId);var visit=state["visit"]as JsonObject;if(visit!=null&&S(visit,"agent")==id&&S(visit,"state")!="due")return PoliceTalk(r,state,visit);
        var c=Confronts(r.PlayerId).FirstOrDefault(c=>S(c,"npc")==id)as JsonObject;return c==null?null:ConfrontTalk(r,c);
    }
    public string? Opening(int player,string id)
    {
        var r=new NativeServiceRequest(C,"POST","/api/npc/"+id+"/talk",player,new(),new(){{"id",id}},new());var response=Talk(r);return response==null?null:S(response,"npc_line");
    }
    public IEnumerable<string> Choices(int player,string id)
    {
        var visit=PoliceState(player)["visit"] as JsonObject;if(visit!=null&&S(visit,"agent")==id)return (visit["offered"]as JsonObject??new()).Select(p=>p.Key).ToArray();var c=Confronts(player).FirstOrDefault(c=>S(c,"npc")==id);return(c?["offered"]as JsonObject??new()).Select(p=>p.Key).ToArray();
    }
    private static JsonObject Line(string text,JsonObject offered,bool end=false,string mood="suspicious")=>new(){["npc_line"]=text,["mood"]=mood,["choices"]=end?new JsonArray():new JsonArray(offered.Select(p=>(JsonNode)JsonValue.Create(p.Key)!).ToArray()),["end"]=end,["gated"]=null,["free"]=false};
    private JsonObject PoliceTalk(NativeServiceRequest r,JsonObject state,JsonObject visit)
    {
        var deeds=VisitDeeds(r.PlayerId,visit);var offered=visit["offered"] as JsonObject??new();string kind=r.Text("kind"),text=r.Text("text");
        if(kind is not("choice"or"free")||text=="") {visit["state"]="talking";offered=new JsonObject{["Yes. I took it. I'm sorry."]="confess",["It wasn't me. I never touched it."]="deny",["I'll give it back. I only borrowed it."]="return"};if(S(visit,"reason")!="talk")offered["I won't pay you a centime."]="refuse";visit["offered"]=offered;SavePolice(r.PlayerId,state);return Line($"{Name(S(visit,"agent"))}, police. You took what was not yours. What do you say?",offered);}
        if(kind!="choice"||offered[text]==null)return new(){["npc_line"]="",["gated"]="no_ai",["free"]=false,["choices"]=new JsonArray(offered.Select(p=>(JsonNode)JsonValue.Create(p.Key)!).ToArray()),["end"]=false};
        string stance=offered[text]!.GetValue<string>();var facts=new JsonArray(deeds.Select(d=>(JsonNode)new JsonObject{["thing"]=d["thing"]!.DeepClone(),["seen"]=N(d,"seen")>0,["owner_saw"]=N(d,"owner_saw")>0,["witnesses"]=A(JsonNode.Parse(S(d,"witnesses","[]"))).Count,["returned"]=S(d,"status")=="returned"}).ToArray());var decision=Decide(new(){["deeds"]=facts,["record"]=state["record"]!.DeepClone(),["fledNow"]=N(visit,"fled"),["stance"]=stance,["money_c"]=Money(r.PlayerId),["reason"]=S(visit,"reason")});return ApplyDecision(r.PlayerId,state,visit,deeds,decision,stance);
    }
    private JsonObject ApplyDecision(int player,JsonObject state,JsonObject visit,JsonObject[] deeds,JsonObject decision,string stance)
    {
        return C.Atomic(()=>{string verdict=S(decision,"verdict"),agent=S(visit,"agent");foreach(var d in deeds){if(S(d,"status")=="open")Undo(d);Home(d);C.Execute("UPDATE deed SET status=$p0,rumour_at=NULL,quiet=0 WHERE id=$p1",verdict=="let_off"?"let_off":verdict=="warning"?"warned":verdict=="fine"?"fined":"arrested",(int)N(d,"id"));}
            int paid=verdict=="arrest"?Money(player):verdict=="fine"?Math.Min((int)N(decision,"fine_c"),Money(player)):0;C.Execute("UPDATE player SET money_c=MAX(0,money_c-$p0) WHERE id=$p1",paid,player);int goods=verdict=="arrest"?C.Execute("DELETE FROM item WHERE player_id=$p0 AND job_id IS NULL AND kind!='pawn_ticket'",player):0;var record=state["record"]!.AsObject();string counter=verdict=="warning"?"warnings":verdict=="fine"?"fines":verdict=="arrest"?"arrests":"";if(counter!="")record[counter]=N(record,counter)+1;string line=verdict=="let_off"?"I will let you off this once. Keep your hands to yourself.":verdict=="warning"?"A warning this time. Do not let me catch you again.":verdict=="fine"?$"{paid} centimes. And give back what you took.":"You will come with me. A night behind the gate may teach you.";var last=new JsonObject{["visit"]=visit["id"]!.DeepClone(),["verdict"]=verdict,["fine_c"]=decision["fine_c"]!.DeepClone(),["paid_c"]=paid,["agent"]=agent,["text"]=line};state["last"]=last;state["visit"]=null;state["settledAt"]=Minute;SavePolice(player,state);Memory(player,agent,$"I {verdict} Jef for thieving.",verdict=="arrest"?8:6,$"Jef was {(verdict=="arrest"?"taken to the prison":verdict=="fine"?"fined by the police":"warned by the police")} for thieving",verdict=="let_off"?0:-2);Trust(player,agent,verdict is "fine"or"arrest"?-1:0);if(verdict is "fine"or"arrest")C.Execute("UPDATE faction_trust SET trust=MAX(-5,trust-$p0) WHERE faction='politie' AND player_id=$p1",verdict=="arrest"?2:1,player);C.Log(player,verdict=="arrest"?"arrested":"police_"+verdict,agent,$"{Name(agent)} of the police gave Jef a {verdict}; {paid} centimes taken.");var response=Line(line,new(),true,verdict=="arrest"?"angry":"cold");response["police"]=last.DeepClone();response["verdict"]=last.DeepClone();if(verdict=="arrest"){var night=CellNight(player,paid,goods);state=PoliceState(player);state["cell"]=night.DeepClone();SavePolice(player,state);response["night"]=night;Arrested?.Invoke(player,agent);}host.PublishState(player);return response;});
    }
    private JsonObject CellNight(int player,int paid,int goods)
    {
        foreach(var hook in host.StopTransportHooks)hook(player);var summary=new JsonArray("You spend the night behind the gate of the prison in the Begijnenstraat.",$"At the gate they empty your pockets: {paid} centimes and {goods} things.","A plank bed, a bucket, a barred window onto the yard.");foreach(var job in C.Rows("SELECT id,title,employer_npc FROM job WHERE status='taken' AND COALESCE(taken_by,1)=$p0",player)){int id=(int)N(job,"id");C.Execute("UPDATE job SET status='failed' WHERE id=$p0",id);C.Execute("DELETE FROM item WHERE job_id=$p0 AND player_id=$p1",id,player);Memory(player,S(job,"employer_npc"),"Jef took my work and then the police took him. It was left undone.",6);summary.Add("Your job is lost: "+S(job,"title")+".");}foreach(var hook in host.EndJobHooks)hook(player);C.Execute("UPDATE player SET sleep=MAX(sleep,6),food=MAX(0,food-2),warmth=MAX(0,warmth-2) WHERE id=$p0",player);C.SetPlayerState(player,"nights_slept",V(State(player,"nights_slept"))+1);C.Log(player,"cell",null,"Jef spent the night in the prison in the Begijnenstraat.");int now=(int)N(host.Clock.View(),"hour")*60+(int)N(host.Clock.View(),"minute"),until=(now<360?360:1800)-now;if(host.MultiplayerEnabled()){host.Rest.CellRest(player,until,Data["prisonGate"]!.DeepClone().AsObject(),summary);CellConsequences(player);return new(){["summary"]=summary,["day"]=Day,["post"]=Data["prisonGate"]!.DeepClone(),["pending"]=true};}var passed=host.Clock.PassTime(player,until);foreach(var hook in host.SleepEndedHooks)hook(player);foreach(var line in A(passed["lines"]))summary.Add(line?.DeepClone());summary.Add("At dawn the warder unlocks the gate. \"Out. And keep your hands to yourself.\"");CellConsequences(player);return new(){["summary"]=summary,["day"]=Day,["post"]=Data["prisonGate"]!.DeepClone(),["turned"]=passed["turned"]?.DeepClone(),["ended"]=passed["ended"]?.DeepClone()};
    }
    private void CellConsequences(int player) { foreach(var npc in C.Rows("SELECT id FROM npc ORDER BY id LIMIT 10")){string id=S(npc,"id");Memory(player,id,"They say Jef was taken to prison for thieving.",5,"Jef was taken to the prison for thieving",-2);Trust(player,id,-1);}C.Execute("UPDATE faction_trust SET trust=MAX(-5,trust-1) WHERE player_id=$p0",player); }
    private void CellEnded(int player,JsonArray lines,JsonObject? ending) { var state=PoliceState(player);var cell=new JsonObject{["summary"]=lines.DeepClone(),["day"]=Day,["post"]=Data["prisonGate"]!.DeepClone()};if(ending!=null)cell["ended"]=ending.DeepClone();state["cell"]=cell;SavePolice(player,state);if(ending==null)foreach(var hook in host.SleepEndedHooks)hook(player);host.PublishState(player); }
    private JsonObject Fled(int player,bool seize)
    {
        var state=PoliceState(player);var visit=state["visit"]as JsonObject;if(visit==null||S(visit,"agent")==""||S(visit,"state")=="due")Refuse("nobody is after you");if(seize){var deeds=VisitDeeds(player,visit!);return ApplyDecision(player,state,visit!,deeds,new(){["verdict"]="arrest",["fine_c"]=150},"refuse");}string agent=S(visit,"agent");visit!["fled"]=N(visit,"fled")+1;state["record"]!["fled"]=N(state["record"],"fled")+1;visit["state"]="due";visit["due"]=Minute+30;visit["agent"]=null;visit["offered"]=new JsonObject();SavePolice(player,state);Trust(player,agent,-2);Memory(player,agent,"Jef ran from me when I called him. A guilty man runs.",7,"Jef ran from the police",-2);C.Log(player,"fled_police",agent,"Jef ran from "+Name(agent)+" of the police.");return NativeCoreClock.Join(new JsonObject{["text"]="Behind you the agent shouts: Stop! In the name of the law!"},PoliceView(player));
    }
